(function () {

    // ARIA-LABEL COUNTER
    function updateAriaLabels(header) {
        header.querySelectorAll('.link-group.link-parent').forEach(function (group, index) {
            group.setAttribute('aria-label', 'Menu column ' + (index + 1));
        });
    }

    function getFocusableChildren(el) {
        return Array.from(el.querySelectorAll(
            'a[href], button, [role="button"], [role="menuitem"], [tabindex]'
        ));
    }

    function setFocusable(el, focusable) {
        getFocusableChildren(el).forEach(function (child) {
            child.setAttribute('tabindex', focusable ? '0' : '-1');
        });
    }


    var A11Y_MAIN_SELECTOR = 'main, [role="main"], #main-content, #content';

    var A11Y_HIDDEN_LAYER_SELECTOR = [
        '.hpv-search-panel',
        '.search-overlay',
