            '.a11y-skip-link{position:fixed;top:8px;left:8px;z-index:100000;padding:12px 20px;' +
            'background:#000;color:#fff;font:600 16px/1.2 sans-serif;border-radius:4px;' +
            'text-decoration:none;transform:translateY(-200%);}' +
