            '.hapvida-sb__search-btn',
            '.hapvida-search-btn',
            '.search-button',
            '.search-toggle',
            '.search-icon',
            '[data-search-trigger]',
            '[aria-label="Pesquisar"]',
            '[aria-label="Abrir pesquisa"]',
            '[aria-label="Abrir busca"]'
        ].join(',');

