            '.hpv-search',
            '.hpv-search-panel',
            '.hapvida-sb',
            '.hapvida-sb__dropdown-wrap',
            '.search-overlay',
            '.search-wrapper',
            '.search-container',
            '.search-bar',
            '[data-search-layer]'
