                if (exceptRoot && exceptRoot.contains(menu)) {
                    return;
                }

                menu.classList.remove('show');
                menu.style.removeProperty('display');
            });

            document.querySelectorAll('.dropdown.show').forEach(function (dropdown) {
                if (exceptRoot && exceptRoot.contains(dropdown)) {
                    return;
                }

                dropdown.classList.remove('show');
            });
        }

        function closeSearchLayer() {
            document.dispatchEvent(new CustomEvent('hapvida:close-search'));

            document.querySelectorAll(
                '.hpv-search-close, ' +
                '.hapvida-sb__close, ' +
                '.search-close, ' +
                '[aria-label="Fechar pesquisa"], ' +
                '[aria-label="Fechar busca"], ' +
                '[aria-label="Limpar pesquisa"], ' +
                '[aria-label="Limpar busca"]'
            ).forEach(function (button) {
                if (isVisible(button)) {
                    button.click();
                }
            });

            document.querySelectorAll(
                '.hpv-search-panel.show, ' +
                '.hpv-search-panel.visible, ' +
                '.hpv-search-panel.is-open, ' +
                '.search-overlay.show, ' +
                '.search-overlay.visible, ' +
                '.search-overlay.is-open, ' +
                '.search-wrapper.show, ' +
                '.search-wrapper.visible, ' +
                '.search-wrapper.is-open, ' +
                '.search-container.show, ' +
                '.search-container.visible, ' +
                '.search-container.is-open, ' +
                '.hapvida-sb__dropdown-wrap .dropdown-menu.show'
