        function initSubmenuTabIndex() {
            container.querySelectorAll('.submenu, .sub-submenu').forEach(function (submenu) {
                setFocusable(submenu, false);
            });
        }

        initSubmenuTabIndex();

        function closeAllMobileSubmenus() {
            container.querySelectorAll('.submenu.visible, .sub-submenu.visible').forEach(function (item) {
