            var clickedMenu = event.target.closest('.primary-link, .secondary-link.has-children, .nav-hamburger');
            var clickedDropdown = event.target.closest(DROPDOWN_TRIGGER_SELECTOR);

            if (clickedSearch || clickedSearchArea) {
                closeHeaderMenusForOverlay();
                closeBootstrapDropdowns(event.target);
                return;
            }

            if (clickedMenu) {
                closeSearchLayer();
                closeBootstrapDropdowns(event.target);
                return;
