        document.addEventListener('focusin', function (event) {
            if (!header.contains(event.target)) {
                return;
            }

            var focusedSearchArea = event.target.closest(SEARCH_AREA_SELECTOR);
            var focusedMenuTrigger = event.target.closest('.primary-link, .secondary-link.has-children, .nav-hamburger');
            var focusedDropdown = event.target.closest(DROPDOWN_TRIGGER_SELECTOR);

            if (focusedSearchArea) {
                closeHeaderMenusForOverlay();
                closeBootstrapDropdowns(event.target);
                return;
            }

            if (focusedMenuTrigger) {
                closeSearchLayer();
                closeBootstrapDropdowns(event.target);
                return;
            }

            if (focusedDropdown) {
                closeSearchLayer();
                closeHeaderMenusForOverlay();
                closeBootstrapDropdowns(event.target);
            }
        }, true);

        function getFocusableRoot(group) {
            return (
                group.querySelector('[role="button"].primary-link') ||
                group.querySelector('a.primary-link')
            );
        }

        // CTRL+SHIFT
        container.addEventListener('keydown', function (e) {
            if (isMobile()) return;

            var isCtrlShift = e.ctrlKey && e.shiftKey;
            var isArrowLeft = e.key === 'ArrowLeft';

            if (!isCtrlShift && !isArrowLeft) return;

            var allGroups = Array.from(container.querySelectorAll('.link-group'));
            var currentIndex = -1;

            allGroups.forEach(function (group, idx) {
                if (group.contains(e.target)) {
                    currentIndex = idx;
                }
            });

            if (currentIndex === -1) return;

            if (isCtrlShift) {
                var nextIndex = currentIndex + 1;
