                    closeSearchLayer();
                    closeBootstrapDropdowns();

                    document.querySelectorAll('.navigation-container .sub-submenu.visible').forEach(function (openSubSubmenu) {
                        if (openSubSubmenu !== subSubmenu) {
                            openSubSubmenu.classList.remove('visible');
                            setFocusable(openSubSubmenu, false);
                        }
