            var isClickOnSearchTrigger = !!event.target.closest(SEARCH_TRIGGER_SELECTOR);
            var isClickOnDropdown = !!event.target.closest(DROPDOWN_TRIGGER_SELECTOR);

            if (!isClickInsideMenu && !isClickOnHamburger) {
